pub enum Msg {
    Ping,
    Heartbeat(u32),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    if let Some(rest) = bytes.strip_prefix("heartbeat:") {
        if let Ok(seq) = rest.parse::<u32>() {
            return Ok(Msg::Heartbeat(seq));
        }
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Heartbeat(seq) => format!("heartbeat:{seq}"),
    }
}

pub fn roundtrip_ping() -> Result<(), String> {
    let encoded = encode(&Msg::Ping);
    if matches!(decode(&encoded), Ok(Msg::Ping)) {
        Ok(())
    } else {
        Err(format!("ping roundtrip failed on {:?}", encoded))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ping_roundtrips() {
        assert_eq!(roundtrip_ping(), Ok(()));
    }

    #[test]
    fn decodes_ping_frame() {
        assert_eq!(decode("ping"), Ok(Msg::Ping));
    }

    #[test]
    fn heartbeat_roundtrips() {
        assert_eq!(decode(&encode(&Msg::Heartbeat(7))), Ok(Msg::Heartbeat(7)));
    }
}
